"""Direct reading of the supplied three-page scan, on 1280px previews.

No timing is inferred from horizontal distance. A tuple records onset, written
duration, observed x/y, and optional written clef/accidental/octave information.
"""
def seq(xs,ys,ds,start=0):
    assert len(xs)==len(ys)==len(ds)
    out=[]
    for x,y,d in zip(xs,ys,ds):
        out.append((start,d,x,y if isinstance(y,list) else [y]));start+=d
    return out

